def transform(grid):
    """
    Transformation rule: For each connected component of 4s,
    if the minimum horizontal distance from any 4 in the component
    to a 3 in the same row is >= 4, then ALL 4s in that component
    become 3s. Otherwise, they stay as 4s.
    """
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find all connected components of 4s
    visited = [[False]*w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4 and not visited[r][c]:
                # BFS to find component
                component = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    component.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == 4 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                # Check if any 4 in this component has min horizontal distance >= 4 to a 3 in same row
                min_dist = float('inf')
                component_has_3_nearby = False

                for pr, pc in component:
                    # Look for 3s in the same row, to the right (since 3s are typically right of 4s)
                    for c3 in range(pc + 1, w):
                        if grid[pr][c3] == 3:
                            dist = c3 - pc
                            min_dist = min(min_dist, dist)
                            if dist >= 4:
                                component_has_3_nearby = True
                            break

                # If all distances are >= 4, convert all 4s in component to 3s
                if component_has_3_nearby and min_dist >= 4:
                    for pr, pc in component:
                        result[pr][pc] = 3

    return result


